def order(a, n):
    if n == 1:
        return 1
    import math
    if math.gcd(a, n) != 1:
        return None

    phi = n
    temp_n = n
    d = 2
    while d * d <= temp_n:
        if temp_n % d == 0:
            phi -= phi // d
            while temp_n % d == 0:
                temp_n //= d
        d += 1
    if temp_n > 1:
        phi -= phi // temp_n

    # The order must divide phi
    # Find divisors of phi
    divisors = []
    for i in range(1, int(phi**0.5) + 1):
        if phi % i == 0:
            divisors.append(i)
            divisors.append(phi // i)

    divisors.sort()
    for d in divisors:
        if pow(a, d, n) == 1:
            return d
    return None

