import math
def get_order(a, n):
    phi = 0
    # This is not the most efficient but for 10000 it is fine
    for i in range(1, n + 1):
        if math.gcd(i, n) == 1:
            phi += 1

    for i in range(1, phi + 1):
        if pow(a, i, n) == 1:
            return i
    return None

print(get_order(3, 10000))
